options.queryReplacement:
={{
[
  Number(
    String($('On form submission').first().json['Doctor'])
      .match(/\d+/)[0]
  ),
  String($('On form submission').first().json['Appointment Date']).slice(0, 10),
  $('On form submission').first().json['Appointment Time'].trim()
]
}}

parameters.message:
={{
`<h2>SmartClinic</h2>
<p>Dear ${$('On form submission').first().json['Patient Name']},</p>
<p>Sorry! Your selected appointment slot is unavailable.</p>
<p><b>Doctor:</b> ${$('On form submission').first().json['Doctor']}</p>
<p><b>Date:</b> ${$('On form submission').first().json['Appointment Date']}</p>
<p><b>Time:</b> ${$('On form submission').first().json['Appointment Time']}</p>
<p>Please select another available appointment time.</p>
<p>Thank you for choosing SmartClinic.</p>`
}}

